package com.masterclass.inventory.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import lombok.*;import java.math.BigDecimal;
@Entity @Table(name="products", indexes={@Index(name="ix_products_sku",columnList="sku",unique=true),@Index(name="ix_products_category",columnList="category_id")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=64) @Column(nullable=false,length=64) private String sku; @NotBlank @Size(max=180) @Column(nullable=false,length=180) private String name; @Column(length=1000) private String description; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="category_id", nullable=false, foreignKey=@ForeignKey(name="fk_products_categories")) private Category category; @NotNull @DecimalMin("0.00") @Column(name="unit_price", nullable=false, precision=12, scale=2) private BigDecimal unitPrice; @Min(0) @Column(name="current_stock", nullable=false) private int currentStock; @Min(0) @Column(name="reorder_level", nullable=false) private int reorderLevel; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ProductStatus status; public void increaseStock(int q){currentStock+=q;} public void decreaseStock(int q){ if(q>currentStock) throw new IllegalArgumentException("Insufficient stock"); currentStock-=q;} }
